def calculate_totals(x, y, z):
    d = {}
    for e in x:
        if y != "" and e[2] != y:
            continue
        if e[3] < z:
            continue
        if e[2] not in d:
            d[e[2]] = 0
        d[e[2]] = d[e[2]] + e[3]
    r = []
    for k in d:
        r.append((k, d[k]))
    r.sort(key=lambda t: -t[1])
    return r


